/* @lc app=leetcode id=936 lang=kotlin */ class Solution { fun movesToStamp(stamp: String, target: String): IntArray = f(target, stamp, listOf())?.toIntArray() ?: intArrayOf() fun f(t: String, s: String, acc: List<Int>): List<Int>? = if (t.all { it == '?' }) acc.reversed() else (0..t.length - s.length).firstOrNull { i -> s.indices.all { t[i + it] == s[it] || t[i + it] == '?' } && s.indices.any { t[i + it] != '?' } }?.let { i -> f(t.substring(0, i) + "?".repeat(s.length) + t.substring(i + s.length), s, acc + i) } }